<script setup>
import {ref,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {Button,Uploader,Dialog} from 'vant';import 'vant/es/button/style';import 'vant/es/uploader/style';import 'vant/es/dialog/style';
const props=defineProps({controller:{type:Object,required:true},model:{type:Object,required:true}}),a=props.controller.actions,canvas=ref(),confirmClear=ref(false);
onMounted(()=>a.attachCanvas(canvas.value));onBeforeUnmount(()=>a.attachCanvas(null));
watch(()=>[props.model.question?.id,props.model.page,props.model.mode],()=>nextTick(()=>a.attachCanvas(canvas.value)));
const photo=files=>a.photo((Array.isArray(files)?files:[files]).map(item=>item.file));
</script>
<template><section class="student-correction-pad"><div class="correction-actions"><Uploader accept="image/jpeg,image/png,image/webp" capture="environment" :show-upload-list="false" :after-read="photo" :disabled="model.locked"><Button :disabled="model.locked" :loading="model.importing">拍照答案</Button></Uploader><Uploader accept="image/jpeg,image/png,image/webp" multiple :show-upload-list="false" :after-read="photo" :disabled="model.locked"><Button :disabled="model.locked">从相册选择</Button></Uploader><Button :disabled="model.locked" :type="model.mode==='handwriting'?'primary':'default'" @click="a.mode('handwriting')">画布手写</Button></div><ol v-if="model.mode==='photo'" class="correction-photos"><li v-for="(image,i) in model.draft.handwriting.photos||[]" :key="i"><img :src="image" :alt="'本次答案第 '+(i+1)+' 页'"/><Button icon="cross" :aria-label="'移除第 '+(i+1)+' 页答案照片'" :disabled="model.locked" @click="a.removePhoto(i)"/></li></ol><div v-show="model.mode!=='photo'"><div class="correction-actions"><Button :disabled="model.locked" :type="model.tool==='pen'?'primary':'default'" :aria-pressed="model.tool==='pen'" @click="a.tool('pen')">画笔</Button><Button :disabled="model.locked" :type="model.tool==='eraser'?'primary':'default'" :aria-pressed="model.tool==='eraser'" @click="a.tool('eraser')">橡皮</Button><Button :disabled="model.locked||!model.canUndo" @click="a.undo">撤销</Button><Button :disabled="model.locked||!model.canRedo" @click="a.redo">重做</Button><Button :disabled="model.locked||!model.canUndo" @click="confirmClear=true">清空本页</Button></div><canvas ref="canvas" width="800" height="1100" :aria-disabled="model.locked" aria-label="手写答案画布，可使用鼠标、手指或手写笔书写" @pointerdown="a.down" @pointermove="a.move" @pointerup="a.up" @pointercancel="a.up" @lostpointercapture="a.up"/><nav class="correction-actions" aria-label="手写原稿页码"><Button icon="arrow-left" aria-label="上一页手写答案" :disabled="model.locked||model.page===0" @click="a.turn(model.page-1)"/><span>第 {{model.page+1}} / {{model.pageCount}} 页</span><Button icon="arrow" aria-label="下一页手写答案" :disabled="model.locked||model.page>=model.pageCount-1" @click="a.turn(model.page+1)"/><Button :disabled="model.locked||model.pageCount>=4" @click="a.addPage">续页</Button></nav></div><Dialog v-model:show="confirmClear" title="清空本页手写答案？"><template #footer><div class="correction-actions"><Button icon="cross" aria-label="关闭清空确认" @click="confirmClear=false"/><Button type="primary" @click="a.clear();confirmClear=false">清空本页</Button></div></template></Dialog></section></template>
<style scoped>.student-correction-pad{min-width:0}.correction-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:14px 0}.student-correction-pad.student-correction-pad :deep(.van-button){min-height:44px;font:inherit}.student-correction-pad canvas{display:block;width:100%;height:auto;max-width:800px;border:1px solid #d9e2d9;background:repeating-linear-gradient(#fff 0px,#fff 39px,#edf0ec 40px);touch-action:none}.correction-photos{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.correction-photos li{position:relative;min-width:0}.correction-photos img{display:block;max-width:100%;height:auto}.correction-photos :deep(.van-button){position:absolute;top:5px;right:5px;width:44px;padding:0;background:#fff}.student-correction-pad.student-correction-pad :deep(.van-dialog .correction-actions){justify-content:center;padding:0 14px}</style>

<style scoped>
/* visual-restore-legacy */
.student-correction-pad{margin:8px 0 16px}.correction-actions{gap:8px;margin:10px 0}.student-correction-pad.student-correction-pad :deep(.van-button){height:auto;min-height:44px;padding:8px 12px;border:1px solid #bbc8ae;border-radius:8px;background:#f0f4eb;color:#263c30;font:inherit}.student-correction-pad.student-correction-pad :deep(.van-button--primary){background:#38694f;border-color:#38694f;color:#fff}.student-correction-pad canvas{max-width:800px;background:#fff;border:1px solid #b9c6a9;border-radius:10px;cursor:crosshair}.correction-photos{display:flex;gap:16px;flex-wrap:wrap}.correction-photos li{width:140px}.correction-photos img{width:140px;height:180px;object-fit:contain;background:#fff;border:1px solid #e5e7eb;border-radius:6px}
</style>
